            x=e.find(tag)
            if x is not None: return x.text
        return '-'
    print(f"{f.split('/')[1]}: nat={g(ide,'natOp')} nNF={g(ide,'nNF')} dEmi={g(ide,'dEmi')} tpNF={g(ide,'tpNF')} idDest={g(ide,'idDest')} cStat={g(ide,'cStat')}")
